def __new__(cls, value, unit=None, dtype=None, copy=True, subok=True, ndmin=0, **kwargs):
    if dtype is None and isinstance(value, np.ndarray) and value.dtype == np.float16:
        dtype = np.float16
    return super().__new__(cls, value, unit=unit, dtype=dtype, copy=copy, subok=subok, ndmin=ndmin, **kwargs)
